package Test {
  port def P { provides event e(v: int); }
  component def Env { port p: P; }
  component def Sys { reversed port p: P; attribute n: int = 0; operation h(v: int) { n = v; } schedule { on receive p.e(v) h(v); } }
  component 'out': Sys;
  component 'view': Env;
  connect ('view'.p, 'out'.p);
  test 'view' of 'out' {
    publish 'view'.p.e(2);
    wait 1ms;
    assert 'out'.n == 2;
  }
}

package Test {
  component def C { attribute x: int = 0; operation 'state'() returns int { return x; } }
  component sys: C;
  component 'in': C;
  test 'state' of sys {
    var v: int = 'in'.'state'();
    assert v == 0;
  }
}

package Test {
