package Lib { component def 'state' { } }
package Test {
  import Lib;
  component def 'state' { }
  component s: 'state';
}

package Test {
  port def 'view' { provides event 'state'(v: int); }
  component def Env { port 'out': 'view'; }
  component def Sys { reversed port 'in': 'view'; attribute 'state': int = 0; operation h(v: int) { 'state' = v; } schedule { on receive 'in'.'state'(v) h(v); } }
  component sys: Sys;
  component 'out': Env;
  connect ('out'.'out', sys.'in');
  test 'in' of sys {
    publish 'out'.'out'.'state'(3);
    wait 1ms;
    assert sys.'state' == 3;
  }
  associate 'out' to 'in';
}
